# Let me analyze neighbor connectivity for the 4s
# Count how many adjacent 4s each 4 has (horizontally and vertically)

def count_neighbor_4s(grid, r, c):
    count = 0
    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:  # up, down, left, right
        nr, nc = r + dr, c + dc
        if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
            if grid[nr][nc] == 4:
                count += 1
    return count

# Analyze each 4 in the grid
print("4s and their neighbor counts:")
for row in range(10):
    for col in range(19):
        if input_grid[row][col] == 4:
            neighbors = count_neighbor_4s(input_grid, row, col)
            print(f"  ({row},{col}): {neighbors} neighbors")

# Maybe the task is: keep 4s with odd neighbor count, remove those with even?
# Or mark differently based on connectivity?

# Try marking 4s based on whether they have ANY neighbors (>= 1) vs isolated (0 neighbors)

# Hypothesis: neighbors count > 0 → 1, no neighbors → 0
output = []
for row in range(10):
    new_row = []
    for col in range(19):
        if input_grid[row][col] == 4:
            if count_neighbor_4s(input_grid, row, col) > 0:
                new_row.append(1)  # has neighbor
            else:
                new_row.append(0)  # isolated
        elif input_grid[row][col] == 9:
            new_row.append(9)  # background
    output.append(new_row)

print("Has neighbor strategy:")
